#!/data/data/com.termux/files/usr/bin/bash
set -euo pipefail
CAMPAIGN=OBSIDIANTI_ARP_FIRST_LIVE_v2.0.5
AUTHORITY=TERMUX_GIT_ONLY
SELF="$(realpath "$0")"
LAUNCHER_SHA256="$(sha256sum "$SELF" | cut -d' ' -f1)"
PAYLOAD_SHA256=3e9ae7ec76fae8b23cfaf0928da3b29b6b8bad3d65fc923721e0f1142c2b17d0
echo "CAMPAIGN=$CAMPAIGN"
echo "AUTHORITY=$AUTHORITY"
echo "LAUNCHER_SHA256=$LAUNCHER_SHA256"
echo "PAYLOAD_SHA256=$PAYLOAD_SHA256"
DIR="$(mktemp -d "${TMPDIR:-${PREFIX:-/data/data/com.termux/files/usr}/tmp}/obs-arp-first-v205.XXXXXXXX")"
trap 'rm -rf "$DIR"' EXIT
base64 -d > "$DIR/payload.tar.gz" <<'END_PAYLOAD_B64'

END_PAYLOAD_B64
printf '%s  %s\n' "$PAYLOAD_SHA256" "$DIR/payload.tar.gz" | sha256sum -c -
mkdir "$DIR/packet"
tar -xzf "$DIR/payload.tar.gz" -C "$DIR/packet" --no-same-owner
python3 "$DIR/packet/driver.py" "$DIR/packet" "$SELF" "$LAUNCHER_SHA256"
